#!/usr/bin/env bash
# Writes services/<service>/.env so each service can run on your PC with  npm run dev
# (Lab 4 style: settings live in .env, never in the code, and .env is never committed).
#   bash infra/write-env.sh                (run after setup-all.sh; setup-all.sh calls it)
set -e
. "$(dirname "$0")/services/_lib.sh"; cd "$ROOT"
[ -z "$COGNITO_USER_POOL_ID" ] && { fail "Run bash infra/setup-all.sh first"; exit 1; }

step "services/*/.env for running on your PC"
for svc in $SERVICES; do
  cat > "services/$svc/.env" <<ENV
# Generated by infra/write-env.sh for running on your PC (npm run dev). Never commit this file.
PORT=$(port_of "$svc")
NODE_ENV=development
SERVICE_NAME=$svc
# AWS services are on Floci (or the preview emulator). Floci accepts any key: these are NOT secrets.
AWS_REGION=$REGION
AWS_ENDPOINT_URL=$ENDPOINT
AWS_ACCESS_KEY_ID=test
AWS_SECRET_ACCESS_KEY=test
COGNITO_USER_POOL_ID=$COGNITO_USER_POOL_ID
COGNITO_CLIENT_ID=$COGNITO_CLIENT_ID
# The website on your PC runs on port 8080 (cd frontend && npm start)
CORS_ORIGINS=http://localhost:8080
# The other services on your PC
CLASS_SERVICE_URL=http://localhost:3002
BOOKING_SERVICE_URL=http://localhost:3003
ATTENDANCE_SERVICE_URL=http://localhost:3004
LOG_GROUP_NAME=/gym/$svc
SHIP_LOGS_TO_CLOUDWATCH=true
REPORTS_KMS_KEY_ID=$KMS_KEY_ARN
EMAIL_SENDER_ADDRESS=${EMAIL_SENDER_ADDRESS:-no-reply@example.com}
ENV
  ok "services/$svc/.env  (port $(port_of "$svc"))"
done
